    let s: i32 = v.iter().sum();
    let p: i32 = v.iter().product();
    println!("{} {} {} {:?} {:?} {:?}", s, p, v.iter().count(), v.iter().min(), v.iter().max(), v.iter().last());
    println!("{} {}", v.iter().fold(0, |a, x| a * 10 + x), v.iter().any(|x| *x == 5));
