}

fn main() {
    let v = vec![1, 2, 3, 4, 5, 6];
    let w = vec![10, 20, 30];
    let z: Vec<(i32, i32)> = v.iter().copied().zip(w.iter().copied()).collect();
    let r: Vec<i32> = v.iter().rev().copied().collect();
    let t: Vec<i32> = v.iter().skip(1).take(3).copied().collect();
    let tw: Vec<i32> = v.iter().take_while(|x| **x < 4).copied().collect();
    let sw: Vec<i32> = v.iter().skip_while(|x| **x < 4).copied().collect();
    println!("{:?} {:?} {:?} {:?} {:?}", z, r, t, tw, sw);
}

