fn tidy(sizes: &mut Vec<i32>) {
    sizes.retain(|s| *s > 4);
    sizes.sort_by_key(|s| -*s);
}

fn top_double(sizes: &Vec<i32>) -> i32 {
    sizes.first().map(|s| s * 2).unwrap_or_else(|| 0)
}


fn main() {
    let mut sizes = vec![1, 7, 4, 6];
    tidy(&mut sizes);
    println!("{:?}", sizes);
    println!("{}", top_double(&sizes));
    let none: Vec<i32> = vec![];
    println!("{}", top_double(&none));
}

