enum AppError { Parse(String), Neg(i32) }
#[derive(Debug)]
struct ParseFail(String);
impl From<ParseFail> for AppError {
    fn from(e: ParseFail) -> AppError { AppError::Parse(e.0) }
}
impl From<i32> for AppError {
    fn from(n: i32) -> Self { AppError::Neg(n) }
}
fn parse(s: &str) -> Result<i32, ParseFail> {
    if s == "x" { Err(ParseFail(String::from("bad"))) } else { Ok(1) }
}
fn neg(n: i32) -> Result<i32, i32> { if n < 0 { Err(n) } else { Ok(n) } }
fn run(s: &str, n: i32) -> Result<i32, AppError> {
    let a = parse(s)?;
    let b = neg(n)?;
    Ok(a + b)
}
fn main() {
    println!("{:?}", run("ok", 2));
    println!("{:?}", run("x", 2));
    println!("{:?}", run("ok", -3));
    println!("{:?}", AppError::from(7));
    let f: AppError = ParseFail(String::from("q")).into();
    println!("{:?}", f);
}

